(function(){const D={username:"_starhwa_",name:"박성화",posts:"4",followers:"5,384",following:"26",bio:"개 산책시키는 사람",link:"youtu.be/marspark03hsdqwjhea",follow:"팔로우",message:"메시지",highlight:"✈️"};const DEF=["data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,"];let imgs;try{imgs=JSON.parse(sessionStorage.getItem('igp_posts_v1'))||DEF}catch(e){imgs=DEF};const map={username:['igpUsername','igpOutUsername'],name:['igpName','igpOutName'],posts:['igpPosts','igpOutPosts'],followers:['igpFollowers','igpOutFollowers'],following:['igpFollowing','igpOutFollowing'],bio:['igpBio','igpOutBio'],link:['igpLink','igpOutLink'],follow:['igpFollowText','igpOutFollow'],message:['igpMessageText','igpOutMessage'],highlight:['igpHighlightTitle','igpOutHighlightTitle']};let saved={};try{saved=JSON.parse(sessionStorage.getItem('igp_state_v1'))||{}}catch(e){};Object.entries(map).forEach(([k,v])=>{const e=document.getElementById(v[0]),o=document.getElementById(v[1]);if(!e||!o)return;e.value=saved[k]??D[k];o.textContent=e.value;e.addEventListener('input',()=>{o.textContent=e.value;save()})});function save(){const o={};Object.entries(map).forEach(([k,v])=>o[k]=document.getElementById(v[0]).value);try{sessionStorage.setItem('igp_state_v1',JSON.stringify(o));sessionStorage.setItem('igp_posts_v1',JSON.stringify(imgs))}catch(e){}}function editors(){const box=document.getElementById('igpPostEditors');box.innerHTML='';imgs.forEach((s,i)=>{const d=document.createElement('div');d.style='display:flex;gap:7px;margin-bottom:7px;align-items:center';d.innerHTML=`<span style="width:22px;font-size:12px">${i+1}</span><input type="file" accept="image/*" style="flex:1"><button type="button" class="btn btn-ghost" style="width:auto;padding:7px 10px">삭제</button>`;d.querySelector('input').addEventListener('change',e=>{const f=e.target.files?.[0];if(!f)return;const r=new FileReader();r.onload=()=>{imgs[i]=r.result;save();render()};r.readAsDataURL(f)});d.querySelector('button').addEventListener('click',()=>{imgs.splice(i,1);save();render()});box.appendChild(d)})}function render(){const g=document.getElementById('igpOutGrid');g.innerHTML='';imgs.forEach(s=>{if(!s)return;const im=document.createElement('img');im.className='igp-post';im.src=s;g.appendChild(im)});editors()}function syncHighlightVisibility(){const cb=document.getElementById('igpShowHighlight'),el=document.querySelector('.igp-highlight');if(!cb||!el)return;el.style.display=cb.checked?'':'none'}document.getElementById('igpShowHighlight')?.addEventListener('change',()=>{syncHighlightVisibility();try{sessionStorage.setItem('igp_show_highlight_v1',document.getElementById('igpShowHighlight').checked?'1':'0')}catch(e){}});try{const sh=sessionStorage.getItem('igp_show_highlight_v1');if(sh!==null)document.getElementById('igpShowHighlight').checked=sh==='1'}catch(e){}syncHighlightVisibility();
document.getElementById('igpAvatar')?.addEventListener('change',e=>{const f=e.target.files?.[0];if(!f)return;const r=new FileReader();r.onload=()=>{document.getElementById('igpOutAvatar').src=r.result;try{sessionStorage.setItem('igp_avatar_v1',r.result)}catch(e){}};r.readAsDataURL(f)});document.getElementById('igpHighlight')?.addEventListener('change',e=>{const f=e.target.files?.[0];if(!f)return;const r=new FileReader();r.onload=()=>{document.getElementById('igpOutHighlight').src=r.result;try{sessionStorage.setItem('igp_highlight_v1',r.result)}catch(e){}};r.readAsDataURL(f)});try{const a=sessionStorage.getItem('igp_avatar_v1'),h=sessionStorage.getItem('igp_highlight_v1');if(a)document.getElementById('igpOutAvatar').src=a;if(h)document.getElementById('igpOutHighlight').src=h}catch(e){}document.getElementById('igpAddPost')?.addEventListener('click',()=>{if(imgs.length<6){imgs.push('');save();render()}});document.getElementById('igpReset')?.addEventListener('click',()=>{if(!confirm('인스타그램 프로필을 기본값으로 복원할까요?'))return;Object.entries(map).forEach(([k,v])=>{document.getElementById(v[0]).value=D[k];document.getElementById(v[1]).textContent=D[k]});imgs=DEF.slice();try{sessionStorage.removeItem('igp_state_v1');sessionStorage.removeItem('igp_avatar_v1');sessionStorage.removeItem('igp_highlight_v1')}catch(e){}document.getElementById('igpOutAvatar').src="data:image/jpeg;base64,";document.getElementById('igpOutHighlight').src="data:image/jpeg;base64,";save();render()});document.getElementById('igpSavePng')?.addEventListener('click',()=>{const t=document.getElementById('instagramProfilePreview'),b=document.getElementById('igpSavePng');if(!t||typeof html2canvas==='undefined'){alert('이미지 생성 기능을 불러오지 못했습니다.');return}b.disabled=true;const old=b.textContent;b.textContent='이미지 생성 중...';html2canvas(t,{backgroundColor:'#fff',scale:3,useCORS:true,allowTaint:true,logging:false}).then(c=>c.toBlob(blob=>{const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='instagram_profile.png';a.click();setTimeout(()=>URL.revokeObjectURL(u),1500);b.textContent=old;b.disabled=false},'image/png')).catch(()=>{alert('PNG 저장에 실패했습니다.');b.textContent=old;b.disabled=false})});render()})();